"""returns a list of index values that match accepted values
acceptedvaluelist should be entered as a list.
[1,-1] is suggested for breathing analysis
"""
def getindexlist(inputlist: Any, acceptedvaluelist: Any) -> object {
    indexlist = [
        i
        for i in range(len(inputlist))
        if (inputlist[i] in acceptedvaluelist)
    ];
    return indexlist;
}

""" If num isn't a power of 2, will return the next higher power of two """
def next_p2(num: Any) -> object {
    rval = 1;
    while (rval < num) {
        rval <<= 1;
    }
    return rval;
}

